"use strict";

// Проверка целостности загрузки.
//
// Приложение собрано из четырёх десятков файлов, и это цена разреза: любой из
// них может не прийти. На проде поймали 503 по app-tep.js ровно в момент
// подмены файлов — половина функций отсутствовала, а человек видел
// «Ошибка интерфейса. Повторите действие», из которой ничего не следует.
//
// Стережём два условия: проверка существует и называет ПРИЧИНУ со следующим
// шагом, а опорные имена в её списке — настоящие функции, а не выдумка.

const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");

const root = path.join(__dirname, "..");
const app = require("./app-source");
const html = fs.readFileSync(path.join(root, "index.html"), "utf8");

// ---------- проверка есть и запускается после загрузки ----------
assert.match(app, /function checkBundleIntegrity\(\)/,
  "проверка целостности обязана существовать: без неё потеря файла выглядит как случайная ошибка");
assert.match(app, /window\.addEventListener\("load"/,
  "проверять раньше полной загрузки нельзя — отложенные файлы ещё идут");

// ---------- сообщение называет причину и следующий шаг ----------
{
  const начало = app.indexOf("function checkBundleIntegrity()");
  const блок = app.slice(начало, начало + 1400);
  assert.match(блок, /Часть приложения не загрузилась/,
    "сообщение обязано называть, ЧТО случилось");
  assert.match(блок, /Обновите страницу/,
    "и что делать дальше");
  assert.match(блок, /проект сохранён/,
    "и снимать главный страх — потерю работы");
  assert.match(блок, /location\.reload\(\)/,
    "кнопка обязана обновлять, а не просто закрывать сообщение");
}

// ---------- опорные имена настоящие ----------
{
  const начало = app.indexOf("const ОПОРНЫЕ_ИМЕНА");
  const список = app.slice(начало, app.indexOf("];", начало));
  const имена = [...список.matchAll(/\["(\w+)",/g)].map(m => m[1]);
  assert.ok(имена.length >= 8, `опорных имён мало (${имена.length}) — потеря файла пройдёт незамеченной`);
  // Ищем по ВСЕМ файлам приложения, а не по частям app.js: опорные имена нарочно
  // взяты из разных файлов — в этом весь смысл проверки. Сверять их только с
  // частями значит не увидеть половину списка (cursorPoint живёт в app-snap.js,
  // parseInputLine — в app-input-line.js).
  const весь = fs.readdirSync(root)
    .filter(f => f.endsWith(".js"))
    .map(f => fs.readFileSync(path.join(root, f), "utf8"))
    .join("\n");
  for (const имя of имена)
    assert.match(весь, new RegExp("function " + имя + "\\s*\\("),
      `опорное имя ${имя} не найдено среди функций: проверка сторожит несуществующее ` +
      `и сработает ложно на каждой загрузке`);
}

console.log("bundle-integrity: OK");
